const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([140.878144, 27.245974]);
  const roi = point.buffer(2000); // 2km radius

  const date1_start = '2013-12-01';
  const date1_end = '2013-12-15';
  const date2_start = '2014-03-23';
  const date2_end = '2014-04-06';

  // 2. Data Acquisition - Try Landsat 8 first
  let col1 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(date1_start, date1_end)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  let col2 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(roi)
    .filterDate(date2_start, date2_end)
    .filter(ee.Filter.lt('CLOUD_COVER', 30));

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Dec 2013 Landsat 8 images: ${size1}`);
  console.log(`Mar 2014 Landsat 8 images: ${size2}`);

  // Fallback to Landsat 7 if needed
  if (size1 === 0) {
    col1 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date1_start, date1_end)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    console.log(`Dec 2013 Landsat 7 images: ${col1.size().getInfo()}`);
  }

  if (size2 === 0) {
    col2 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
      .filterBounds(roi)
      .filterDate(date2_start, date2_end)
      .filter(ee.Filter.lt('CLOUD_COVER', 30));
    console.log(`Mar 2014 Landsat 7 images: ${col2.size().getInfo()}`);
  }

  if (col1.size().getInfo() === 0 || col2.size().getInfo() === 0) {
    console.log('No images found for one or both dates');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Cloud masking and water detection
  function maskCloudsAndGetWater(image) {
    const qaMask = image.select('QA_PIXEL');
    const cloudMask = qaMask.bitwiseAnd(1 << 3).eq(0)
      .and(qaMask.bitwiseAnd(1 << 4).eq(0));

    // Calculate NDWI: (Green - NIR) / (Green + NIR)
    const green = image.select('SR_B3').multiply(0.0000275).add(-0.2);
    const nir = image.select('SR_B5').multiply(0.0000275).add(-0.2);
    const ndwi = green.subtract(nir).divide(green.add(nir));

    // Water is NDWI > 0, Land is NDWI <= 0
    const land = ndwi.lt(0).updateMask(cloudMask);
    return land.rename('land');
  }

  const img1 = col1.first();
  const img2 = col2.first();

  const land1 = maskCloudsAndGetWater(img1);
  const land2 = maskCloudsAndGetWater(img2);

  // Check valid pixels
  const count1 = land1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('land').getInfo();

  const count2 = land2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('land').getInfo();

  console.log(`Valid land pixels Dec 2013: ${count1}`);
  console.log(`Valid land pixels Mar 2014: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid land pixels after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Connected component analysis to count islands
  const landSum1 = land1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('land').getInfo();

  const landSum2 = land2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('land').getInfo();

  console.log(`Total land pixels Dec 2013: ${landSum1}`);
  console.log(`Total land pixels Mar 2014: ${landSum2}`);

  // Use connectedPixelCount to identify separate islands
  const connected1 = land1.connectedPixelCount(100, false);
  const connected2 = land2.connectedPixelCount(100, false);

  // Count number of distinct island groups (components > threshold)
  const islands1 = connected1.gt(10).reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('land').getInfo();

  const islands2 = connected2.gt(10).reduceRegion({
    reducer: ee.Reducer.countDistinct(),
    geometry: roi,
    scale: 30,
    maxPixels: 1e9
  }).get('land').getInfo();

  console.log(`Island components Dec 2013: ${islands1}`);
  console.log(`Island components Mar 2014: ${islands2}`);

  if (islands1 === null || islands2 === null) {
    console.log('Island detection failed');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if pattern matches: 2 islands -> 1 island
  if (islands1 === 2 && islands2 === 1) {
    console.log('Pattern confirmed: Two islands merged into one');
    console.log('<answer>A</answer>');
  } else {
    console.log(`Pattern does not match: ${islands1} -> ${islands2} islands`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
